package com.portfolio.features.integration.github.entity;
import com.portfolio.features.user.entity.AppUser; import jakarta.persistence.*; import java.time.*; import java.util.*; import lombok.*;
@Entity @Table(name="github_connections") @Getter @Setter @NoArgsConstructor public class GitHubConnection { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id") private AppUser user; private long githubUserId; private String githubUsername; @Column(columnDefinition="TEXT") private String githubAvatarUrl; @Column(columnDefinition="TEXT") private String accessToken; private String scope; private LocalDateTime connectedAt,updatedAt; @PrePersist void created(){connectedAt=updatedAt=LocalDateTime.now();}@PreUpdate void updated(){updatedAt=LocalDateTime.now();} }
